    std::uint64_t *aWUSaltF = pDomainSaltSet->mWandererUpdate.mSaltF;
    std::uint64_t *aWUSaltG = pDomainSaltSet->mWandererUpdate.mSaltG;
    std::uint64_t *aWUSaltH = pDomainSaltSet->mWandererUpdate.mSaltH;
