    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xF8E52996D6BDA065ULL + 0xF76EA3FBE318FDBEULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xE219BF4315053DB3ULL + 0xD49342BE93736EB6ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0xBB8C6261C03D2D31ULL + 0x83EE1885F56D8606ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xFCD54D943CD976F9ULL + 0xD051B2F1F7311DD0ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0x8D126C76842DB64FULL + 0xE704B997F6CDEE4DULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0xDBE9C87DB284AFDFULL + 0xEDA51A724A38B3DFULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0xB50CA67B1C57B03DULL + 0xB4DE6B7621EE6D42ULL);
