    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseB(pNonce * 0xE7D1E4398FC7D8ABULL + 0xA000592C94ABEB0EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0xA2DB2C6051D2340DULL + 0xC0C3C6DC9090F596ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0xBA4B61502F813F63ULL + 0x85B941F73636D542ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0xE8E03BC2F22260EBULL + 0xDC48EC1726B99896ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseB(pNonce * 0x8D32F71C582F659DULL + 0x8B7F6E874AACBDE7ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseA(pNonce * 0x851F74EFB4AC9D8FULL + 0xFC2C3B2D51D02213ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseC(pNonce * 0xFCDF8DDE881B851BULL + 0xFAC46731EDF29815ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordP = TwistMix64::DiffuseA(pNonce * 0xB28F3CCB58DFCAE7ULL + 0xF8335F043B7FB441ULL);
    std::uint64_t aDomainWordIngress = pConstants->mIngress;
