            aOrbiterG = ((aWandererD + RotL64(aCross, 13U)) + RotL64(aCarry, 57U)) + 0x6C847B3746CC2ADFULL;
            aOrbiterF = ((aWandererA + RotL64(aIngress, 60U)) + 0xA5F47E185F87111AULL) + aOASaltE[(((511U - aIndex) + 82U)) & S_SALT1];
