            aScatter = (RotL64(aIngress, 51U) + RotL64(aCross, 5U)) + (RotL64(aPrevious, 34U) ^ RotL64(aCarry, 21U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterE = (aWandererI + RotL64(aScatter, 29U)) + 0x53510872A2B1B482ULL;
            aOrbiterC = (aWandererG + RotL64(aPrevious, 41U)) + 0xC8DA03105EE0E12AULL;
            aOrbiterB = ((aWandererB + RotL64(aCross, 4U)) + 0x2CAA1048083290EAULL) + aOASaltA[(((511U - aIndex) + 277U)) & S_SALT1];
            aOrbiterA = (((aWandererH + RotL64(aIngress, 11U)) + RotL64(aCarry, 57U)) + 0xC8F6972ADA025EC2ULL) + aOASaltB[((aIndex + 307U)) & S_SALT1];
