            aWandererD = aWandererD + ((((RotL64(aScatter, 5U) + aOrbiterE) + RotL64(aOrbiterG, 47U)) + RotL64(aCarry, 43U)) + aWUSaltC[((aIndex + 161U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aPrevious, 53U) + aOrbiterK) + RotL64(aOrbiterH, 39U)) + aWUSaltA[(((511U - aIndex) + 13U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aScatter, 40U) + RotL64(aOrbiterK, 57U)) + aOrbiterC);
            aWandererG = aWandererG ^ (((RotL64(aIngress, 57U) + RotL64(aOrbiterE, 19U)) + aOrbiterK) + aWUSaltB[(((511U - aIndex) + 413U)) & S_SALT1]);
            aWandererK = aWandererK + ((((RotL64(aCross, 23U) + aOrbiterF) + RotL64(aOrbiterB, 51U)) + RotL64(aCarry, 19U)) + aWUSaltE[((aIndex + 432U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 19U) + aOrbiterB) + RotL64(aOrbiterC, 24U));
