            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x69CC51BF36F5133AULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0x44DE09C103963BE0ULL) ^ aOUSaltB[((aIndex + 201U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x2C8CA6347A63D10FULL), 53U);
