            aOrbiterC = (((aWandererG + RotL64(aCross, 21U)) + RotL64(aCarry, 57U)) + 0x1856585D8B04AD96ULL) + aOASaltC[((aIndex + 374U)) & S_SALT1];
            aOrbiterH = ((aWandererK + RotL64(aScatter, 41U)) + 0x7B580EDA696AF031ULL) + aOASaltD[((aIndex + 316U)) & S_SALT1];
            aOrbiterG = (aWandererF + RotL64(aPrevious, 35U)) + 0xDA24E83A1A0E504DULL;
